function transfer(address _to, uint256 _value) public returns (bool) {
                require(_value > 0);
                require(balanceOf[msg.sender].sub(_value) >= 0);
                require(balanceOf[_to].add(_value) >= balanceOf[_to]);
                balanceOf[msg.sender] = balanceOf[msg.sender].sub(_value);
                balanceOf[_to] = balanceOf[_to].add(_value);
                emit Transfer(msg.sender, _to, _value);
                return true;
            }

function transferFrom(address _from, address _to, uint256 _amount) public returns (bool) {
                require(_amount > 0);
                require(balanceOf[_from].sub(_amount) >= 0);
                require(balanceOf[_to].add(_amount) >= balanceOf[_to]);
                require(allowed[_from][msg.sender] >= _amount);
                balanceOf[_from] = balanceOf[_from].sub(_amount);
                balanceOf[_to] = balanceOf[_to].add(_amount);
                allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_amount);
                emit Transfer(_from, _to, _amount);
                return true;
            }

function approve(address _spender, uint256 _amount) public returns (bool) {
                require(_amount > 0);
                require(balanceOf[msg.sender].sub(_amount) >= 0);
                require(allowed[msg.sender][_spender] >= _amount);
                allowed[msg.sender][_spender] = _amount;
                emit Approval(msg.sender, _spender, _amount);
                return true;
            }

function blacklistAccount(address _account) public onlyOwner() {
                blacklistedAccounts[_account] = true;
            }

function mintTokens(uint256 _amount) public onlyOwner() {
                totalSupply = totalSupply.add(_amount);
                balanceOf[msg.sender] = balanceOf[msg.sender].add(_amount);
                emit Transfer(address(0), msg.sender, _amount);
            }
